s12-assign-cookies.code:
// Approach: Sort children by greed and cookies by size. Give the smallest sufficient cookie to the
//   least greedy unserved child.
#include <algorithm>
#include <vector>
using namespace std;
int findContentChildren(vector<int> greed, vector<int> cookies) {
    sort(greed.begin(), greed.end());
    sort(cookies.begin(), cookies.end());
    int child = 0;
    // Give each cookie to the least greedy unserved child it can satisfy.
    for (int size : cookies) {
        // A cookie too small for this child cannot satisfy any later child.
        if (child < (int)greed.size() && size >= greed[child])
            ++child;
    }
    return child;
}

s12-fractional-knapsack-problem.code:
// Approach: Sort items by value-to-weight ratio descending. Take each whole item while possible, then
//   the needed fraction of the next one.
#include <algorithm>
#include <vector>
using namespace std;
struct Item { int value; int weight; };
double fractionalKnapsack(vector<Item> items, int capacity) {
    sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
        return (long long)a.value * b.weight > (long long)b.value * a.weight;
    });
    double total = 0;
    // After sorting by value per weight, take as much as possible of each best item.
    for (const Item& item : items) {
        // No capacity remains, so later items cannot add value.
        if (capacity == 0) break;
        // Problem assumes positive weights and nonnegative values.
        int taken = min(capacity, item.weight); // the last item may be fractional
        total += (double)item.value * taken / item.weight;
        capacity -= taken;
    }
    return total;
}

s12-greedy-algorithm-to-find-minimum-num.code:
// Approach: For the standard Indian denomination set, take as many as possible of each coin from
//   largest to smallest. This greedy rule is not valid for arbitrary coin systems.
#include <vector>
using namespace std;
vector<int> minimumIndianCoins(int amount) {
    const int coins[] = {1000, 500, 100, 50, 20, 10, 5, 2, 1};
    vector<int> answer;
    // The chosen coins cannot represent a negative amount.
    if (amount < 0) return answer;
    for (int coin : coins) { // use larger denominations before smaller ones
        while (amount >= coin) {
            answer.push_back(coin);
            amount -= coin;
        }
    }
    return answer;
}

s12-lemonade-change.code:
// Approach: Track $5 and $10 notes. For a $20 payment, prefer giving one $10 and one $5, preserving
//   $5 notes for later customers.
#include <vector>
using namespace std;
bool lemonadeChange(const vector<int>& bills) {
    int fives = 0, tens = 0;
    for (int bill : bills) {
        // A five-dollar bill needs no change and becomes useful for later customers.
        if (bill == 5) ++fives;
        // A ten-dollar bill needs one five-dollar bill as change.
        else if (bill == 10) {
            // Without a five-dollar bill, a ten-dollar sale is impossible.
            if (fives == 0) return false;
            --fives;
            ++tens;
        // A twenty-dollar bill needs fifteen dollars of change.
        } else if (bill == 20) {
            if (tens > 0 && fives > 0) { // save two extra $5 notes
                --tens; --fives;
            // If no ten-dollar bill is available, use three fives instead.
            } else if (fives >= 3) fives -= 3;
            else return false;
        } else return false;
    }
    return true;
}

s12-valid-paranthesis-checker.code:
// Approach: For a string with '(' , ')' and '*', track the minimum and maximum possible open counts.
//   '*' may be ')', '(' or empty.
#include <string>
using namespace std;
bool checkValidString(const string& s) {
    int minimumOpen = 0, maximumOpen = 0;
    for (char ch : s) {
        // An opening bracket increases both possible counts of unmatched opens.
        if (ch == '(') { ++minimumOpen; ++maximumOpen; }
        // A closing bracket uses one possible unmatched opening bracket.
        else if (ch == ')') { --minimumOpen; --maximumOpen; }
        // A star may act as a closing or opening bracket, widening the range.
        else if (ch == '*') { --minimumOpen; ++maximumOpen; }
        else return false;
        if (maximumOpen < 0) return false; // even treating all '*' as '(' fails
        // The minimum cannot be negative: a star can be treated as empty.
        if (minimumOpen < 0) minimumOpen = 0;
    }
    return minimumOpen == 0;
}

s12-n-meetings-in-one-room.code:
// Approach: Sort meetings by finish time. Taking the earliest finishing compatible meeting leaves the
//   most room for later meetings.
#include <algorithm>
#include <utility>
#include <vector>
using namespace std;
int maxMeetings(const vector<int>& start, const vector<int>& finish) {
    // Each start time has a matching finish time.
    vector<pair<int,int>> meetings;
    for (int i = 0; i < (int)start.size(); ++i)
        meetings.push_back({finish[i], start[i]});
    sort(meetings.begin(), meetings.end());
    int count = 0;
    int lastFinish = 0;
    bool chosen = false;
    // Choose the earliest finishing compatible meeting to leave maximum room later.
    for (auto [end, begin] : meetings) {
        if (!chosen || begin > lastFinish) { // choose the earliest compatible finish
            ++count;
            lastFinish = end;
            chosen = true;
        }
    }
    return count;
}

s12-jump-game.code:
// Approach: Scan left to right while tracking the farthest reachable index. If the current index
//   exceeds that reach, the end is impossible.
#include <algorithm>
#include <vector>
using namespace std;
bool canJump(const vector<int>& jumps) {
    long long farthest = 0;
    for (int i = 0; i < (int)jumps.size(); ++i) {
        if (i > farthest) return false; // this position cannot be reached
        farthest = max(farthest, (long long)i + jumps[i]);
    }
    return true;
}

s12-jump-game-2.code:
// Approach: Treat all positions reachable with the current number of jumps as one layer. When the
//   scan reaches the layer's end, take another jump to the farthest next reach.
#include <algorithm>
#include <vector>
using namespace std;
int minJumps(const vector<int>& jumps) {
    int n = (int)jumps.size();
    // The starting index is already the destination for size zero or one.
    if (n <= 1) return 0;
    long long end = 0, farthest = 0;
    int count = 0;
    // Scan all positions reachable with the current jump before committing to the next jump.
    for (int i = 0; i < n - 1; ++i) {
        // An index beyond the farthest reachable point means the end is unreachable.
        if (i > farthest) return -1;
        farthest = max(farthest, (long long)i + jumps[i]);
        if (i == end) { // finish one BFS-like jump layer
            ++count;
            end = farthest;
            // Once the current jump reaches the last index, the count is final.
            if (end >= n - 1) return count;
        }
    }
    return -1;
}

s12-minimum-number-of-platforms-required.code:
// Approach: Sort arrival and departure times separately. Sweep chronologically, increasing platforms
//   for an arrival and freeing one for a departure.
#include <algorithm>
#include <vector>
using namespace std;
int minimumPlatforms(vector<int> arrival, vector<int> departure) {
    // Every train has one arrival and one departure.
    sort(arrival.begin(), arrival.end());
    sort(departure.begin(), departure.end());
    int waiting = 0, maximum = 0;
    int in = 0, out = 0, n = (int)arrival.size();
    while (in < n) {
        // An arrival before or at the next departure still needs its own platform.
        if (arrival[in] <= departure[out]) {
            // A train arriving at the exact departure time needs a platform.
            maximum = max(maximum, ++waiting);
            ++in;
        } else {
            --waiting;
            ++out;
        }
    }
    return maximum;
}

s12-job-sequencing-problem.code:
// Approach: Process jobs by descending profit. Assign each to its latest free slot at or before its
//   deadline; disjoint-set links occupied slots to the next earlier free one.
#include <algorithm>
#include <numeric>
#include <utility>
#include <vector>
using namespace std;
struct Job { int id; int deadline; int profit; };
int freeSlot(vector<int>& parent, int slot) {
    // A free slot is its own representative in the disjoint-set structure.
    if (parent[slot] == slot) return slot;
    return parent[slot] = freeSlot(parent, parent[slot]);
}
pair<int, long long> jobSequencing(vector<Job> jobs) {
    sort(jobs.begin(), jobs.end(), [](const Job& a, const Job& b) {
        return a.profit > b.profit;
    });
    int slots = (int)jobs.size(); // no more than n one-unit jobs can be done
    vector<int> parent(slots + 1);
    iota(parent.begin(), parent.end(), 0);
    int scheduled = 0;
    long long profit = 0;
    for (const Job& job : jobs) {
        // A job with no profit or no valid deadline cannot improve the schedule.
        if (job.profit <= 0 || job.deadline <= 0) continue;
        int slot = freeSlot(parent, min(job.deadline, slots));
        // No free time slot remains before this job's deadline.
        if (slot == 0) continue;
        ++scheduled;
        profit += job.profit;
        parent[slot] = freeSlot(parent, slot - 1); // occupy this slot
    }
    return {scheduled, profit};
}

s12-candy.code:
// Approach: Give every child one candy. A left-to-right pass satisfies higher ratings than the left
//   neighbor; a right-to-left pass satisfies the right neighbor.
#include <algorithm>
#include <numeric>
#include <vector>
using namespace std;
long long candy(const vector<int>& rating) {
    // Each child needs more candy than a lower-rated neighbor.
    int n = (int)rating.size();
    vector<int> sweets(n, 1);
    // The left-to-right pass satisfies ratings compared with left neighbors.
    for (int i = 1; i < n; ++i)
        // A child rated above the left neighbor needs one more candy.
        if (rating[i] > rating[i - 1]) sweets[i] = sweets[i - 1] + 1;
    // The right-to-left pass also satisfies right neighbors without undoing the first pass.
    for (int i = n - 2; i >= 0; --i)
        // A child rated above the right neighbor needs one more candy.
        if (rating[i] > rating[i + 1])
            sweets[i] = max(sweets[i], sweets[i + 1] + 1);
    return accumulate(sweets.begin(), sweets.end(), 0LL);
}

s12-program-for-shortest-job-first-or-sj.code:
// Approach: When all jobs are ready at time zero, running shorter jobs first minimizes total waiting
//   time. Add each job's start time to the waiting total.
#include <algorithm>
#include <vector>
using namespace std;
double averageWaitingTime(vector<int> burstTimes) {
    // No jobs means no waiting time.
    if (burstTimes.empty()) return 0;
    sort(burstTimes.begin(), burstTimes.end());
    long long elapsed = 0, waiting = 0;
    for (int duration : burstTimes) {
        waiting += elapsed;  // this job waited for all earlier jobs
        elapsed += duration;
    }
    return (double)waiting / burstTimes.size();
}

s12-program-for-least-recently-used-lru-.code:
// Approach: Keep recent pages in a list and their positions in a hash map. A hit moves its page to
//   the front; a miss evicts the oldest page if full.
#include <list>
#include <unordered_map>
#include <vector>
using namespace std;
int lruPageFaults(const vector<int>& pages, int capacity) {
    // Without cache space, every page reference is a miss.
    if (capacity <= 0) return (int)pages.size();
    list<int> recent; // front = most recently used
    unordered_map<int, list<int>::iterator> where;
    int faults = 0;
    for (int page : pages) {
        auto it = where.find(page);
        // A cached page is a hit; move it to the most recently used position.
        if (it != where.end()) {
            recent.splice(recent.begin(), recent, it->second);
            continue;
        }
        ++faults;
        // Evict the least recently used page when a miss finds the cache full.
        if ((int)recent.size() == capacity) {
            where.erase(recent.back());
            recent.pop_back();
        }
        recent.push_front(page);
        where[page] = recent.begin();
    }
    return faults;
}

s12-insert-interval.code:
// Approach: With sorted non-overlapping intervals, copy those entirely before the new one, merge
//   every overlap into it, then append the rest.
#include <algorithm>
#include <vector>
using namespace std;
vector<vector<int>> insertInterval(const vector<vector<int>>& intervals,
                                   vector<int> added) {
    vector<vector<int>> answer;
    int i = 0, n = (int)intervals.size();
    // Intervals ending before the new one cannot overlap; keep them unchanged.
    while (i < n && intervals[i][1] < added[0])
        answer.push_back(intervals[i++]);
    // Absorb every overlapping interval, extending the new interval's bounds.
    while (i < n && intervals[i][0] <= added[1]) {
        // Closed intervals touching at an endpoint overlap.
        added[0] = min(added[0], intervals[i][0]);
        added[1] = max(added[1], intervals[i][1]);
        ++i;
    }
    answer.push_back(added);
    // Everything left begins after the merged interval, so append it unchanged.
    while (i < n) answer.push_back(intervals[i++]);
    return answer;
}

s12-merge-intervals.code:
// Approach: Sort intervals by start. The last output interval either absorbs the next overlapping
//   interval or stays separate.
#include <algorithm>
#include <vector>
using namespace std;
vector<vector<int>> mergeIntervals(vector<vector<int>> intervals) {
    // Sort by start; overlapping intervals can extend the current end.
    sort(intervals.begin(), intervals.end());
    vector<vector<int>> answer;
    for (const auto& interval : intervals) {
        // Start a new merged interval only when there is no overlap.
        if (answer.empty() || answer.back()[1] < interval[0])
            answer.push_back(interval);
        else
            answer.back()[1] = max(answer.back()[1], interval[1]);
    }
    return answer;
}

s12-non-overlapping-intervals.code:
// Approach: Sort by ending time and keep each interval that starts at or after the previous chosen
//   end. All skipped intervals must be removed.
#include <algorithm>
#include <vector>
using namespace std;
int eraseOverlapIntervals(vector<vector<int>> intervals) {
    sort(intervals.begin(), intervals.end(), [](const auto& a, const auto& b) {
        // Sort by finish time; a tied finish may be ordered by start without affecting the greedy choice.
        return a[1] == b[1] ? a[0] < b[0] : a[1] < b[1];
    });
    int removed = 0;
    int lastEnd = 0;
    bool chosen = false;
    for (const auto& interval : intervals) {
        // Keep an interval when it starts after the last selected one ends.
        if (!chosen || interval[0] >= lastEnd) {
            lastEnd = interval[1];
            chosen = true;
        } else {
            ++removed; // keeping the earlier finish is always at least as good
        }
    }
    return removed;
}
